/**
 * Re-reads one subject and writes its document. A missing or archived row is
 * left out of the index, including when a stale document is still there.
 */
async function reindexSubject(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  switch (subjectKind) {
    case "issue": {
      const issue = await issueRepo.findIssueById(orgId, subjectId as Issue["id"]);
      if (!issue) {
        await removeFromIndex(orgId, "issue", subjectId);
        return;
      }
      await indexIssue(orgId, issue);
      return;
    }
    case "comment": {
      const comment = await commentRepo.findCommentById(
        orgId,
        subjectId as Comment["id"],
      );
      if (!comment) {
        await removeFromIndex(orgId, "comment", subjectId);
        return;
      }
      await indexComment(orgId, comment);
      return;
    }
    case "project": {
      const project = await projectRepo.findProjectById(
        orgId,
        subjectId as Project["id"],
      );
      if (!project) {
        await removeFromIndex(orgId, "project", subjectId);
        return;
      }
      await indexProject(orgId, project);
      return;
    }
  }
}

