import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { emit } from "@/lib/event-bus";
import { getDb, searchIndex } from "@/server/db";
import { eq } from "drizzle-orm";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import * as searchRepo from "@/server/repositories/search-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let detach: Unsubscribe;
let enterprise: Tenant;
let starter: Tenant;
let growth: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
  enterprise = await createTenant("entsearch", "enterprise");
  starter = await createTenant("startersearch", "starter");
  growth = await createTenant("growthsearch", "growth");
});

afterAll(() => {
  detach();
  cleanup();
});

function query(
  tenant: Tenant,
  q: string,
  kinds: Array<"issue" | "comment" | "project"> = ["issue", "comment", "project"],
  projectId?: Tenant["project"]["id"],
) {
  return searchService.search(tenant.actors.member, {
    orgId: tenant.org.id,
    q,
    kinds,
    ...(projectId !== undefined ? { projectId } : {}),
    limit: 25,
    cursor: null,
  });
}

describe("search behaviour", () => {
  it("finds a colon title on starter without refusing", async () => {
    const issue = await issueService.createIssue(
      starter.actors.member,
      issueInput(starter.org.id, starter.project.id, { title: "Release 2: hotfix" }),
    );
    const hits = await query(starter, "Release 2: hotfix", ["issue", "comment", "project"]);
    expect(hits.total).toBe(1);
    expect(hits.items[0]?.id).toBe(issue.id);
  });

  it("applies kind and project tokens instead of searching them literally", async () => {
    const issue = await issueService.createIssue(
      enterprise.actors.member,
      issueInput(enterprise.org.id, enterprise.project.id, { title: "deploy pipeline" }),
    );
    const comment = await commentService.createComment(enterprise.actors.member, {
      orgId: enterprise.org.id,
      issueId: issue.id,
      body: "flaky deploy helper",
      parentId: null,
      mentionedUserIds: [],
    });

    const byKind = await query(enterprise, "kind:comment flaky", ["issue"]);
    expect(byKind.total).toBe(1);
    expect(byKind.items[0]).toMatchObject({ kind: "comment", id: comment.id });

    const plural = await query(enterprise, "in:comments flaky", ["issue", "project"]);
    expect(plural.items.map((hit) => hit.id)).toEqual([comment.id]);

    const scoped = await query(
      enterprise,
      `project:${enterprise.project.id} deploy`,
      ["issue"],
    );
    expect(scoped.items.map((hit) => hit.id)).toContain(issue.id);
    expect(scoped.items.some((hit) => hit.kind === "comment")).toBe(true);

    const viaFilter = await query(enterprise, "flaky", ["comment"], enterprise.project.id);
    expect(viaFilter.total).toBe(1);
    expect(viaFilter.items[0]?.id).toBe(comment.id);
  });

  it("matches percent and underscore literally", async () => {
    await issueService.createIssue(
      enterprise.actors.member,
      issueInput(enterprise.org.id, enterprise.project.id, { title: "100% complete" }),
    );
    await issueService.createIssue(
      enterprise.actors.member,
      issueInput(enterprise.org.id, enterprise.project.id, { title: "100 items left" }),
    );
    await issueService.createIssue(
      enterprise.actors.member,
      issueInput(enterprise.org.id, enterprise.project.id, { title: "snake_case tool" }),
    );
    await issueService.createIssue(
      enterprise.actors.member,
      issueInput(enterprise.org.id, enterprise.project.id, { title: "snake case tool" }),
    );

    const percent = await query(enterprise, "100%", ["issue"]);
    expect(percent.items.map((hit) => hit.title)).toEqual(["100% complete"]);

    const snake = await query(enterprise, "snake_case", ["issue"]);
    expect(snake.items.map((hit) => hit.title)).toEqual(["snake_case tool"]);
  });

  it("hides comments from a growth workspace even when asked for", async () => {
    const issue = await issueService.createIssue(
      growth.actors.member,
      issueInput(growth.org.id, growth.project.id, { title: "growthonly marker" }),
    );
    await commentService.createComment(growth.actors.member, {
      orgId: growth.org.id,
      issueId: issue.id,
      body: "growthonly marker in a comment",
      parentId: null,
      mentionedUserIds: [],
    });

    const hits = await query(growth, "growthonly", ["issue", "comment", "project"]);
    expect(hits.total).toBe(1);
    expect(hits.items[0]).toMatchObject({ kind: "issue", id: issue.id });
  });

  it("reindexes comments and projects and leaves archived issues out", async () => {
    const issue = await issueService.createIssue(
      enterprise.actors.member,
      issueInput(enterprise.org.id, enterprise.project.id, { title: "reindex-issue-marker" }),
    );
    const comment = await commentService.createComment(enterprise.actors.member, {
      orgId: enterprise.org.id,
      issueId: issue.id,
      body: "reindex-comment-marker",
      parentId: null,
      mentionedUserIds: [],
    });
    const project = await projectService.createProject(enterprise.actors.admin, {
      orgId: enterprise.org.id,
      name: "reindex-project-marker",
      slug: "reindex-project",
      key: "RIP",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });

    await searchService.removeFromIndex(enterprise.org.id, "comment", comment.id);
    await searchService.removeFromIndex(enterprise.org.id, "project", project.id);

    await emit("search.reindex_requested", {
      orgId: enterprise.org.id,
      actorId: enterprise.actors.admin.userId,
      occurredAt: new Date().toISOString() as never,
      subjectKind: "comment",
      subjectId: comment.id,
    });
    await emit("search.reindex_requested", {
      orgId: enterprise.org.id,
      actorId: enterprise.actors.admin.userId,
      occurredAt: new Date().toISOString() as never,
      subjectKind: "project",
      subjectId: project.id,
    });

    const commentHits = await query(enterprise, "reindex-comment-marker", ["comment"]);
    expect(commentHits.total).toBe(1);
    const projectHits = await query(enterprise, "reindex-project-marker", ["project"]);
    expect(projectHits.total).toBe(1);

    await issueService.archiveIssue(enterprise.actors.member, enterprise.org.id, issue.id);
    await searchRepo.upsertSearchDocument(
      enterprise.org.id,
      "issue",
      issue.id,
      "reindex-issue-marker",
      issue.projectId,
    );
    await emit("search.reindex_requested", {
      orgId: enterprise.org.id,
      actorId: null,
      occurredAt: new Date().toISOString() as never,
      subjectKind: "issue",
      subjectId: issue.id,
    });
    const archived = await query(enterprise, "reindex-issue-marker", ["issue"]);
    expect(archived.total).toBe(0);
  });

  it("rebuild writes the issue project id onto comments", async () => {
    const issue = await issueService.createIssue(
      enterprise.actors.member,
      issueInput(enterprise.org.id, enterprise.project.id, { title: "rebuild host" }),
    );
    const comment = await commentService.createComment(enterprise.actors.member, {
      orgId: enterprise.org.id,
      issueId: issue.id,
      body: "rebuild-comment-marker",
      parentId: null,
      mentionedUserIds: [],
    });

    await searchRepo.upsertSearchDocument(
      enterprise.org.id,
      "comment",
      comment.id,
      comment.body,
      null,
    );

    await runSearchReindexJob(enterprise.org.id);

    const row = getDb()
      .select()
      .from(searchIndex)
      .where(eq(searchIndex.subjectId, comment.id))
      .get();
    expect(row?.projectId).toBe(enterprise.project.id);

    const hits = await query(enterprise, "rebuild-comment-marker", ["comment"], enterprise.project.id);
    expect(hits.total).toBe(1);
